constexpr const char* kWebPage = R"DWHTML(<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Dragonwilds Server</title>
<style>
  @font-face{font-family:'Jancient';src:url('/assets/Jancient-Regular.ttf') format('truetype');font-weight:400;font-style:normal;font-display:swap}
    :root { color-scheme: dark; font-family: system-ui, sans-serif; background: #101816; color: #eef3e9; }
    body { margin: 0; min-height: 100vh; display: grid; place-items: center; }
    main { width: min(90vw, 32rem); padding: 2rem; background: #1d2924; border: 1px solid #496257; border-radius: 1rem; box-shadow: 0 20px 60px #0005; }
    h1 { margin: 0 0 .4rem; font-size: 1.75rem; }
    nav { display: flex; gap: 1rem; margin-bottom: 1.5rem; }
    nav a[aria-current="page"] { color: #eef3e9; font-weight: 700; }
    .subtle { color: #b5c6b9; }
    .count { font-size: 4rem; font-weight: 700; line-height: 1.1; margin: 1.5rem 0 0; }
    ul { padding: 0; list-style: none; display: grid; gap: .65rem; }
    a { color: #a7e7bd; text-decoration: none; }
    a:hover, a:focus { text-decoration: underline; }
    .player { display: block; padding: .8rem 1rem; background: #26372f; border-radius: .6rem; }
    .error { color: #ffb7a8; }
  </style>
</head>
<body>
  <main>
    <nav><a href="/" aria-current="page">Online</a><a href="/players">Players</a><a href="/kills">Kills</a><a href="/map">Map</a><a href="/recipe-unlocks">Recipe Unlocks</a></nav>
    <h1>Dragonwilds Server</h1>
    <div id="state" class="subtle" role="status" aria-live="polite">Checking server...</div>
    <div id="count" class="count">—</div>
    <div class="subtle">players online</div>
    <ul id="players"></ul>
  </main>
  <script>
    const state = document.getElementById('state');
    const count = document.getElementById('count');
    const list = document.getElementById('players');
    async function refresh() {
      try {
        const response = await fetch('/api/players', { cache: 'no-store' });
        if (!response.ok) throw new Error('Server data unavailable');
        const data = await response.json();
        if (!Array.isArray(data.players) || data.count !== data.players.length) throw new Error('Invalid server data');
        count.textContent = String(data.count);
        list.replaceChildren();
        for (const player of data.players) {
          const item = document.createElement('li');
          const link = document.createElement('a');
          link.className = 'player';
          link.textContent = String(player.name);
          link.href = '/player?id=' + encodeURIComponent(String(player.id));
          item.appendChild(link);
          list.appendChild(item);
        }
        state.textContent = 'Live player status';
        state.classList.remove('error');
      } catch (_) {
        count.textContent = '—';
        list.replaceChildren();
        state.textContent = 'Server data unavailable';
        state.classList.add('error');
      }
    }
    refresh();
    setInterval(refresh, 10000);
  </script>
</body>
</html>)DWHTML";

